package vn.svframe.mythicmobsfabric;
import net.fabricmc.api.ModInitializer;import net.fabricmc.fabric.api.event.lifecycle.v1.ServerLifecycleEvents;import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;import net.fabricmc.fabric.api.command.v2.CommandRegistrationCallback;import static net.minecraft.server.command.CommandManager.literal;
public final class MythicMobsFabricMod implements ModInitializer {public static final String ID="mythicmobsfabric";private long ticks;public void onInitialize(){ServerLifecycleEvents.SERVER_STARTED.register(s->System.out.println("[MythicMobs-Fabric] runtime online"));ServerTickEvents.END_SERVER_TICK.register(s->ticks++);CommandRegistrationCallback.EVENT.register((d,r,e)->d.register(literal("mythicmobsfabric").requires(s->s.hasPermissionLevel(2)).then(literal("status").executes(c->{c.getSource().sendFeedback(()->net.minecraft.text.Text.literal("MythicMobs Fabric ticks="+ticks),false);return 1;}))));}}
